import{_t as e,it as t,n,rt as r}from"./chunks/framework.XJu5filh.js";import"./chunks/assets.DWopfgZq.js";var i=JSON.parse(`{"title":"主页","description":"","frontmatter":{},"headers":[],"relativePath":"feature/dashboard.md","filePath":"feature/dashboard.md","lastUpdated":1792237609000}`),a={name:`feature/dashboard.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="主页" tabindex="-1">主页 <a class="header-anchor" href="#主页" aria-label="Permalink to “主页”">​</a></h1><p>主页是一个综合性面板，由一个个单独的信息面板组成。桌面与扩展可以在<a href="./setting#主页设置">设置页面</a>进行开关和排序，移动端目前没有该设置入口。</p><h2 id="每日统计" tabindex="-1">每日统计 <a class="header-anchor" href="#每日统计" aria-label="Permalink to “每日统计”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img1.png" alt="alt text" width="307" height="143"></p><p>自动记录每天进行的副本讨伐次数，按设备本地日期统计，跨日后在读取新的相关游戏数据时重置。右上角分别代表消耗的AP(悬浮显示小红数)、AAP和BP数量。扫荡类副本不会记录怪物图标，但会正常记录消耗。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>点击怪物图标可切换展示右上角的小图钉标识，表示是否固定展示，固定展示时每天只清空数据但图标保留。可用于需要提醒自己刷某些副本的场景，比如刷六龙成就时固定展示六龙，每天提醒自己刷几只。</p></div><p><img src="/tarou-docs/assets/img/dashboard-img16.png" alt="alt text" width="310" height="425"></p><p>进入救援检索页面会自动获取当前参战中的副本信息，主要用于查看是否达到参战上限。检索页面刷新即可更新数据，不需要切到多人战斗页面，前提是不要选中优先表示活动副本。</p><p><img src="/tarou-docs/assets/img/dashboard-img2.png" alt="alt text" width="725" height="373"></p><p>桌面与扩展点击标题【每日统计】，可弹窗展示每日掉落情况，右上角可切换展示顺序；数据随每日统计一起重置。移动端目前没有该详情弹窗。</p><h2 id="点数资源" tabindex="-1">点数资源 <a class="header-anchor" href="#点数资源" aria-label="Permalink to “点数资源”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img3.png" alt="alt text" width="306" height="274"></p><p>基本等同于首页用户面板中的点数数据，不用再点开二级菜单去确认详细信息，达到上限时数字会变色。</p><h2 id="活动信息" tabindex="-1">活动信息 <a class="header-anchor" href="#活动信息" aria-label="Permalink to “活动信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img4.png" alt="alt text" width="305" height="278"></p><p>点进活动主页就会自动获取并展示活动信息，不同的活动展示内容会略有不同，大致分为标题展示的重要点数，以及主体的各种任务进展情况，右上角的时间表示最后的更新时间。</p><p>任务勾选框的颜色分为<code>蓝色</code>和<code>黄色</code>，蓝色代表日常，黄色代表单次任务。达到数量要求时会自动勾选。</p><p>只有进行适配过的活动才会展示信息，目前支持的活动有：<code>炼金活动</code>、<code>神灭战</code>、<code>月末战货</code>、<code>古战场</code>、<code>四象降临</code>、<code>转世外传</code>、<code>剧情活动</code>、<code>剧情复刻</code>、<code>十天众战记</code>、<code>公会战</code>。</p><p>活动结束后会自动隐藏面板。</p><h2 id="素材监控" tabindex="-1">素材监控 <a class="header-anchor" href="#素材监控" aria-label="Permalink to “素材监控”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img5.png" alt="alt text" width="307" height="97"></p><p>基本等同于游戏自带的底部素材监控，区别在于全部展示，省去了来回翻页的操作。如果设定了数量，达到数量后数字会变色。</p><h2 id="抽卡资源" tabindex="-1">抽卡资源 <a class="header-anchor" href="#抽卡资源" aria-label="Permalink to “抽卡资源”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img6.png" alt="alt text" width="307" height="135"></p><p>进入抽卡界面时自动获取当前的抽卡资源，并换算成xx井，还会自动计算攒井天数。</p><p>抽卡时会自动记录抽卡结果。桌面与扩展点击天数旁的记录按钮查看结果；各端均可点击重置按钮重新计算攒井天数。移动端不提供抽卡记录弹窗。</p><h2 id="扫荡副本" tabindex="-1">扫荡副本 <a class="header-anchor" href="#扫荡副本" aria-label="Permalink to “扫荡副本”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img9.png" alt="alt text" width="306" height="216"></p><p>为了方便扫荡，增加了扫荡副本面板，点击副本图片可以直接跳转相应链接，相当于书签。</p><p><img src="/tarou-docs/assets/img/dashboard-img10.png" alt="alt text" width="307" height="227"></p><p>首次以及之后每天刷新需要点击Pro副本一览更新数据。</p><h2 id="探险信息" tabindex="-1">探险信息 <a class="header-anchor" href="#探险信息" aria-label="Permalink to “探险信息”">​</a></h2><p><img src="/tarou-docs/assets/img/dashboard-img11.png" alt="alt text" width="307" height="139"></p><p>展示当前和探险结束时的元气，以及元气全回复、探险完成的倒计时。探险倒计时会在战斗完成时扣除相应的时间，可以在设置中开启探险完成时的通知。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>扫荡副本比较特别，加快的时间跟你扫荡副本中包含的副本次数有关，所以不会实时变更倒计时，需要自己去探险页面刷新数据。</p></div><h2 id="探险配装" tabindex="-1">探险配装 <a class="header-anchor" href="#探险配装" aria-label="Permalink to “探险配装”">​</a></h2><p>桌面与扩展点击探险信息标题可以打开探险配装弹窗，通过获取游戏中的数据，自动展示符合条件的配装。移动端目前没有该弹窗入口。</p><p><img src="/tarou-docs/assets/img/dashboard-img12.png" alt="alt text" width="518" height="161"></p><p>顶部为队长及队员的基础信息，通过进入探险首页和选择地图后获取。</p><p><img src="/tarou-docs/assets/img/dashboard-img13.png" alt="alt text" width="560" height="195"></p><p>中间为地图信息和各种筛选项，你可以指定符合条件的数量，队员以及某些装备。括号内为符合当前条件的组合总数。</p><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p><img src="/tarou-docs/assets/img/dashboard-img14.png" alt="alt text" width="299" height="155"></p><p>装备数据必须在清空当前地图配置的队员和装备后，点击头部和武器获取对应数据。</p></div><p><img src="/tarou-docs/assets/img/dashboard-img15.png" alt="alt text" width="503" height="382"></p><p>底部则是展示符合条件的配装，按照属性总和降序排列，只展示前10种组合。属性后面的数值颜色，绿色和红色分别代表满足和不满足地图需求。</p>`,44)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};